def overlap_size(a_start: int, a_end: int, b_start: int, b_end: int) -> int:
    if not (0 <= a_start <= 65535 and 0 <= a_end <= 65535 and 0 <= b_start <= 65535 and 0 <= b_end <= 65535):
        return -1
    if a_start > a_end or b_start > b_end:
        return -1

    max_start = a_start if a_start > b_start else b_start
    min_end = a_end if a_end < b_end else b_end

    overlap = min_end - max_start
    return overlap if overlap > 0 else 0
